// frontend/src/pages/Auth.js
// Login + Google Authenticator 2FA — clean single-input TOTP

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

// ── SHARED UI ─────────────────────────────────────────────────────────────────
function AuthBox({ children }) {
  return (
    <div style={{ minHeight:'100vh', display:'flex', alignItems:'center',
      justifyContent:'center', background:'var(--bv-bg)', padding:16 }}>
      <div style={{ width:'100%', maxWidth:400, background:'var(--bv-bg2)',
        border:'1px solid var(--bv-bd)', borderRadius:14,
        boxShadow:'0 8px 40px rgba(0,0,0,0.3)' }}>

        <div style={{ padding:'22px 28px 18px', textAlign:'center',
          borderBottom:'1px solid var(--bv-bd)' }}>
          <div style={{ width:48, height:48,
            background:'linear-gradient(135deg,var(--bv-accent),var(--bv-accent-dark))',
            borderRadius:12, display:'flex', alignItems:'center', justifyContent:'center',
            margin:'0 auto 12px', fontSize:18, fontWeight:700, color:'#fff' }}>BV</div>
          <div style={{ fontSize:19, fontWeight:600, color:'var(--bv-txt)', lineHeight:1 }}>BackupVault</div>
          <div style={{ fontSize:11.5, color:'var(--bv-cyan)', marginTop:4, fontWeight:500 }}>
            Infrastructure · Worktual Innovations
          </div>
        </div>

        <div style={{ padding:'22px 28px 26px' }}>{children}</div>
      </div>
    </div>
  );
}

function ErrBox({ msg }) {
  if (!msg) return null;
  return (
    <div style={{ color:'var(--bv-red)', fontSize:12, marginBottom:14,
      padding:'8px 12px', background:'var(--bv-red-bg)', borderRadius:7,
      border:'1px solid var(--bv-red-border)',
      display:'flex', alignItems:'center', gap:8 }}>
      <i className="ti ti-alert-circle" style={{ fontSize:14, flexShrink:0 }}/>
      {msg}
    </div>
  );
}

function OkBox({ msg }) {
  if (!msg) return null;
  return (
    <div style={{ color:'var(--bv-green)', fontSize:12, marginBottom:14,
      padding:'8px 12px', background:'var(--bv-green-bg)', borderRadius:7,
      border:'1px solid var(--bv-green)',
      display:'flex', alignItems:'center', gap:8 }}>
      <i className="ti ti-circle-check" style={{ fontSize:14, flexShrink:0 }}/>
      {msg}
    </div>
  );
}

function Label({ children }) {
  return (
    <div style={{ fontSize:11.5, fontWeight:600, color:'var(--bv-txt2)',
      marginBottom:5, letterSpacing:'.02em' }}>{children}</div>
  );
}

function PrimaryBtn({ loading, children, disabled, onClick, type='submit' }) {
  return (
    <button type={type} onClick={onClick} disabled={loading || disabled}
      style={{ width:'100%', padding:'10px 0',
        background: (loading || disabled) ? 'var(--bv-bd2)' : 'var(--bv-accent)',
        color:'#fff', border:'none', borderRadius:9, fontSize:13.5,
        fontWeight:600, cursor: (loading||disabled) ? 'not-allowed' : 'pointer',
        display:'flex', alignItems:'center', justifyContent:'center', gap:8,
        marginBottom:10, transition:'background .15s' }}>
      {loading
        ? <><i className="ti ti-loader"
            style={{ animation:'bvspin .7s linear infinite', fontSize:15 }}/> Please wait...</>
        : children}
    </button>
  );
}

const inputStyle = {
  width:'100%', padding:'9px 12px', background:'var(--bv-input)',
  border:'1px solid var(--bv-bd2)', color:'var(--bv-txt)',
  borderRadius:8, fontSize:13, outline:'none', boxSizing:'border-box',
  fontFamily:'inherit',
};

// ── LOGIN PAGE ────────────────────────────────────────────────────────────────
export function LoginPage() {
  const [view,      setView]      = useState('login'); // login|totp|forgot|otp
  const [email,     setEmail]     = useState('');
  const [password,  setPassword]  = useState('');
  const [totpCode,  setTotpCode]  = useState('');
  const [forgot,    setForgot]    = useState('');
  const [otp,       setOtp]       = useState({ code:'', newPass:'', confirm:'' });
  const [loading,   setLoading]   = useState(false);
  const [error,     setError]     = useState('');
  const [msg,       setMsg]       = useState('');
  const [showPass,  setShowPass]  = useState(false);

  const { login, loginWithToken } = useAuth();
  const navigate = useNavigate();

  function reset() { setError(''); setMsg(''); }
  function goLogin() { reset(); setView('login'); setTotpCode(''); }

  // ── Sign in ────────────────────────────────────────────────────────────
  async function handleLogin(e) {
    e.preventDefault();
    reset(); setLoading(true);
    try {
      const res = await login(email.trim(), password);
      if (res && res.requires_2fa) {
        setView('totp');
        return;
      }
      navigate('/dashboard');
    } catch(err) {
      setError(err.message || 'Login failed');
    } finally {
      setLoading(false);
    }
  }

  // ── TOTP verify ────────────────────────────────────────────────────────
  async function handleTotp(e) {
    e.preventDefault();
    const code = String(totpCode).replace(/\s/g,'');
    if (code.length < 6) { setError('Please enter the 6-digit code'); return; }
    reset(); setLoading(true);
    try {
      const res = await fetch('/api/auth/login', {
        method:  'POST',
        headers: { 'Content-Type': 'application/json' },
        body:    JSON.stringify({
          email:      email.trim(),
          password:   password,
          totp_code:  code,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Verification failed');
      loginWithToken(data);
      navigate('/dashboard');
    } catch(err) {
      setError(err.message || 'Verification failed');
      setTotpCode('');
    } finally {
      setLoading(false);
    }
  }

  // ── Forgot password ────────────────────────────────────────────────────
  async function handleForgot(e) {
    e.preventDefault(); reset(); setLoading(true);
    try {
      const res = await fetch('/api/auth/forgot-password', {
        method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ email: forgot.trim() }),
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error);
      setMsg('OTP sent to your email.'); setView('otp');
    } catch(err) { setError(err.message); } finally { setLoading(false); }
  }

  // ── Reset password ─────────────────────────────────────────────────────
  async function handleReset(e) {
    e.preventDefault();
    if (otp.newPass !== otp.confirm) { setError('Passwords do not match'); return; }
    if (otp.newPass.length < 8)      { setError('Minimum 8 characters'); return; }
    reset(); setLoading(true);
    try {
      const res = await fetch('/api/auth/reset-password-with-otp', {
        method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ email:forgot, otp:otp.code, newPassword:otp.newPass }),
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error);
      setMsg('Password reset successfully.'); goLogin();
    } catch(err) { setError(err.message); } finally { setLoading(false); }
  }

  // ── VIEW: TOTP ─────────────────────────────────────────────────────────
  if (view === 'totp') return (
    <AuthBox>
      <div style={{ textAlign:'center', marginBottom:24 }}>
        <div style={{ width:60, height:60, borderRadius:'50%',
          background:'var(--bv-blue-dim)', border:'2px solid var(--bv-blue)',
          display:'flex', alignItems:'center', justifyContent:'center',
          margin:'0 auto 16px', fontSize:28 }}>🔐</div>
        <div style={{ fontSize:16, fontWeight:600, color:'var(--bv-txt)', marginBottom:8 }}>
          Two-Factor Authentication
        </div>
        <div style={{ fontSize:12, color:'var(--bv-txt2)', lineHeight:1.7 }}>
          Open <strong>Google Authenticator</strong> on your phone<br/>
          Enter the 6-digit code for:<br/>
          <span style={{ color:'var(--bv-cyan)', fontWeight:500 }}>{email}</span>
        </div>
      </div>

      <form onSubmit={handleTotp}>
        <Label>Authenticator code</Label>
        <input
          type="text"
          inputMode="numeric"
          value={totpCode}
          onChange={e => setTotpCode(e.target.value.replace(/\D/g,'').slice(0,6))}
          placeholder="6-digit code"
          maxLength={6}
          autoFocus
          style={{ ...inputStyle, textAlign:'center', fontSize:28,
            letterSpacing:10, fontFamily:'monospace', fontWeight:700,
            marginBottom:16, padding:'12px 0' }}
        />

        <ErrBox msg={error}/>

        <PrimaryBtn loading={loading} disabled={totpCode.length < 6}>
          <i className="ti ti-shield-check" style={{ fontSize:16 }}/> Verify & Sign In
        </PrimaryBtn>

        <div style={{ padding:'9px 12px', background:'var(--bv-bg3)', borderRadius:8,
          fontSize:11, color:'var(--bv-txt2)', marginBottom:14, lineHeight:1.6 }}>
          <i className="ti ti-key" style={{ color:'var(--bv-amber)', marginRight:6 }}/>
          <strong>No phone?</strong> Enter one of your 10 backup codes (format: <code>XXXX-XXXX</code>) instead.
        </div>

        <button type="button" onClick={goLogin}
          style={{ background:'none', border:'none', color:'var(--bv-blue)', fontSize:12,
            width:'100%', textAlign:'center', cursor:'pointer', padding:'4px 0' }}>
          <i className="ti ti-arrow-left" style={{ marginRight:5 }}/>
          Back to sign in
        </button>
      </form>
    </AuthBox>
  );

  // ── VIEW: FORGOT ───────────────────────────────────────────────────────
  if (view === 'forgot') return (
    <AuthBox>
      <div style={{ marginBottom:18 }}>
        <div style={{ fontSize:16, fontWeight:600, color:'var(--bv-txt)', marginBottom:4 }}>
          Forgot password
        </div>
        <div style={{ fontSize:12, color:'var(--bv-txt2)' }}>
          We'll send a one-time reset code to your email
        </div>
      </div>
      <form onSubmit={handleForgot}>
        <Label>Email address</Label>
        <input type="email" value={forgot} onChange={e => setForgot(e.target.value)}
          placeholder="you@worktual.tech" style={{ ...inputStyle, marginBottom:14 }}
          required autoFocus/>
        <ErrBox msg={error}/><OkBox msg={msg}/>
        <PrimaryBtn loading={loading}>Send Reset Code</PrimaryBtn>
        <button type="button" onClick={goLogin}
          style={{ background:'none', border:'none', color:'var(--bv-blue)', fontSize:12,
            width:'100%', textAlign:'center', cursor:'pointer' }}>
          <i className="ti ti-arrow-left" style={{ marginRight:5 }}/>Back to sign in
        </button>
      </form>
    </AuthBox>
  );

  // ── VIEW: OTP RESET ────────────────────────────────────────────────────
  if (view === 'otp') return (
    <AuthBox>
      <div style={{ marginBottom:18 }}>
        <div style={{ fontSize:16, fontWeight:600, color:'var(--bv-txt)', marginBottom:4 }}>
          Reset password
        </div>
        <div style={{ fontSize:12, color:'var(--bv-txt2)' }}>
          OTP sent to <strong style={{ color:'var(--bv-cyan)' }}>{forgot}</strong>
        </div>
      </div>
      <form onSubmit={handleReset}>
        <Label>OTP Code</Label>
        <input value={otp.code} onChange={e => setOtp(p=>({...p,code:e.target.value}))}
          placeholder="123456" maxLength={6} autoFocus required
          style={{ ...inputStyle, textAlign:'center', fontFamily:'monospace',
            fontSize:20, letterSpacing:6, fontWeight:600, marginBottom:14 }}/>
        <Label>New password</Label>
        <input type="password" value={otp.newPass}
          onChange={e => setOtp(p=>({...p,newPass:e.target.value}))}
          placeholder="Min. 8 characters" required minLength={8}
          style={{ ...inputStyle, marginBottom:14 }}/>
        <Label>Confirm password</Label>
        <input type="password" value={otp.confirm}
          onChange={e => setOtp(p=>({...p,confirm:e.target.value}))}
          placeholder="Repeat password" required
          style={{ ...inputStyle, marginBottom:14 }}/>
        <ErrBox msg={error}/><OkBox msg={msg}/>
        <PrimaryBtn loading={loading}>Reset Password</PrimaryBtn>
        <button type="button" onClick={goLogin}
          style={{ background:'none', border:'none', color:'var(--bv-blue)', fontSize:12,
            width:'100%', textAlign:'center', cursor:'pointer' }}>
          <i className="ti ti-arrow-left" style={{ marginRight:5 }}/>Back to sign in
        </button>
      </form>
    </AuthBox>
  );

  // ── VIEW: LOGIN ────────────────────────────────────────────────────────
  return (
    <AuthBox>
      <div style={{ fontSize:15.5, fontWeight:600, color:'var(--bv-txt)', marginBottom:18 }}>
        Sign in to your account
      </div>

      <form onSubmit={handleLogin}>
        <Label>Email address</Label>
        <input type="email" value={email} onChange={e => setEmail(e.target.value)}
          placeholder="admin@worktual.tech" required autoFocus
          style={{ ...inputStyle, marginBottom:14 }}/>

        <Label>Password</Label>
        <div style={{ position:'relative', marginBottom:14 }}>
          <input type={showPass?'text':'password'} value={password}
            onChange={e => setPassword(e.target.value)}
            required style={{ ...inputStyle, paddingRight:40 }}/>
          <button type="button" onClick={() => setShowPass(v => !v)}
            style={{ position:'absolute', right:10, top:'50%', transform:'translateY(-50%)',
              background:'none', border:'none', color:'var(--bv-txt3)',
              cursor:'pointer', padding:0, lineHeight:1 }}>
            <i className={`ti ti-${showPass?'eye-off':'eye'}`} style={{ fontSize:17 }}/>
          </button>
        </div>

        <ErrBox msg={error}/>

        <PrimaryBtn loading={loading}>
          <i className="ti ti-login" style={{ fontSize:16 }}/> Sign In
        </PrimaryBtn>
      </form>

      <button type="button"
        onClick={() => { reset(); setView('forgot'); }}
        style={{ background:'none', border:'none', color:'var(--bv-blue)',
          fontSize:12, cursor:'pointer', padding:'0 0 14px', display:'block' }}>
        Forgot password?
      </button>

      <div style={{ padding:'9px 12px', background:'var(--bv-bg3)', borderRadius:8,
        fontSize:11, color:'var(--bv-txt3)', lineHeight:1.7 }}>
        <i className="ti ti-shield-lock" style={{ marginRight:6, color:'var(--bv-blue)' }}/>
        If Google Authenticator is enabled on your account, you'll be prompted
        for the 6-digit code after your password.
      </div>

      <div style={{ marginTop:16, paddingTop:14, borderTop:'1px solid var(--bv-bd)',
        fontSize:11, color:'var(--bv-txt3)', textAlign:'center' }}>
        <i className="ti ti-lock" style={{ marginRight:5 }}/>
        Invite-only access. Contact your administrator.
      </div>
    </AuthBox>
  );
}

// No public registration
export function RegisterPage() {
  const navigate = useNavigate();
  useEffect(() => { navigate('/login', { replace:true }); }, [navigate]);
  return null;
}
